solutions.naive:
class Solution:
    def strStr(self, haystack: str, needle: str) -> int:
        n, m = len(haystack), len(needle)
        for start in range(n - m + 1):
            j = 0
            while j < m and haystack[start + j] == needle[j]:
                j += 1
            if j == m:
                return start
        return -1

